actions.script:
def sourceMap = [instagram:'Instagram', youtube:'YouTube', facebook:'Facebook', linkedin:'LinkedIn',
    x:'X', twitter:'X', google:'GoogleSearch', googlesearch:'GoogleSearch', googleads:'GoogleAds',
    whatsapp:'WhatsApp', email:'Email', website:'Website', web:'Website', referral:'Referral',
    phone:'Phone', partner:'Partner', event:'Event', exhibition:'Exhibition', import:'Import',
    marketplace:'Marketplace', walkin:'WalkIn', other:'Other', unknown:'Unknown',
    coldcall:'ColdCall', socialmedia:'SocialMedia', searchads:'SearchAds']
def rawSource = utmSource?.toString()?.trim()?.toLowerCase(java.util.Locale.ROOT)
def mappedSource = rawSource ? sourceMap[rawSource.replaceAll(/[^a-z]/, '')] : null
if (!leadSourceId) leadSourceId = mappedSource ?: (captureMethod == 'Manual' ? null : 'Unknown')
['sourceDetail','utmSource','utmMedium','utmCampaign','utmContent','utmTerm',
 'landingPageUrl','referrerUrl','externalSubmissionId'].each { field ->
    if (context[field]?.toString()?.length() > 255) ec.message.addError(field + ' must be at most 255 characters.')
}
if (landingPageUrl && !(landingPageUrl ==~ /(?i)https?:\/\/.+/)) ec.message.addError('Landing page must be an HTTP or HTTPS URL.')
if (referrerUrl && !(referrerUrl ==~ /(?i)https?:\/\/.+/)) ec.message.addError('Referrer must be an HTTP or HTTPS URL.')
if (leadSourceId) {
    def src = ec.entity.find('zenith.erp.crm.LeadSource').condition('leadSourceId', leadSourceId).one()
    if (!src || src.isActive != 'Y' || (src.organizationPartyId && src.organizationPartyId != organizationPartyId))
        ec.message.addError('Choose an active lead source for your organization.')
} else ec.message.addError('Choose a lead source, or explicitly choose Unknown.')
if (campaignId) {
    def campaign = ec.entity.find('zenith.erp.crm.CrmCampaign').condition('campaignId', campaignId).one()
    if (!campaign || campaign.organizationPartyId != organizationPartyId || campaign.isActive != 'Y')
        ec.message.addError('Choose an active campaign for your organization.')
}
def existing = ec.entity.find('zenith.erp.crm.Lead').condition('organizationPartyId', organizationPartyId).list()
def duplicate = existing.find { row -> (email && row.email?.equalsIgnoreCase(email)) ||
    (mobile && row.mobile?.replaceAll(/\D/, '') == mobile.replaceAll(/\D/, '')) }
if (duplicate && allowDuplicate != 'Y') ec.message.addError('Possible duplicate lead ' + duplicate.leadId +
    '. Review it before creating another; select Allow duplicate to confirm.')
def contacts = ec.entity.find('zenith.erp.contacts.ContactListView')
    .condition('ownerPartyId', organizationPartyId).list()
def matchingContact = contacts.find { row -> (email && row.emailAddress?.equalsIgnoreCase(email)) ||
    (mobile && row.phoneNumber?.replaceAll(/\D/, '') == mobile.replaceAll(/\D/, '')) }
if (matchingContact && allowDuplicate != 'Y') ec.message.addError('Matching contact ' + matchingContact.partyId +
    ' already exists. Review it before creating a separate lead.')

def editable = ['statusId','firstName','lastName','companyName','designation','email','phone','mobile',
    'website','address','city','regionCode','postalCode','taxRegistrationNumber','taxIdNumber',
    'leadSourceId','sourceDetail','campaignId','rating','estimatedAmount','estimatedCloseDate','description','lostReason']
leadUpdate = [leadId:leadId]
editable.each { key -> if (context.containsKey(key)) leadUpdate[key] = context[key] }
if (leadUpdate.containsKey('firstName')) leadUpdate.firstName = leadUpdate.firstName?.trim()
if (leadUpdate.containsKey('email')) leadUpdate.email = leadUpdate.email?.trim()?.toLowerCase(java.util.Locale.ROOT)
if (leadUpdate.containsKey('mobile')) leadUpdate.mobile = leadUpdate.mobile?.trim()

def sourceMap = [instagram:'Instagram', youtube:'YouTube', facebook:'Facebook', linkedin:'LinkedIn',
    x:'X', twitter:'X', google:'GoogleSearch', googlesearch:'GoogleSearch', googleads:'GoogleAds',
    whatsapp:'WhatsApp', email:'Email', website:'Website', web:'Website', referral:'Referral',
    phone:'Phone', partner:'Partner', event:'Event', exhibition:'Exhibition', import:'Import',
    marketplace:'Marketplace', walkin:'WalkIn', other:'Other', unknown:'Unknown',
    coldcall:'ColdCall', socialmedia:'SocialMedia', searchads:'SearchAds']
def raw = utmSource?.trim()?.toLowerCase(java.util.Locale.ROOT)
if (!leadSourceId && raw) leadSourceId = sourceMap[raw.replaceAll(/[^a-z]/, '')] ?: 'Unknown'
if (!leadSourceId) ec.message.addError('Choose a source for this touch.')
else {
    def src = ec.entity.find('zenith.erp.crm.LeadSource').condition('leadSourceId', leadSourceId).one()
    if (!src || src.isActive != 'Y' || (src.organizationPartyId && src.organizationPartyId != lead.organizationPartyId))
        ec.message.addError('Choose a valid source.')
}

def settings = ownStages.collectEntries { [(it.opportunityStageId):it] }
def active = stageCandidates.findAll { !['SoClosedWon','SoClosedLost'].contains(it.opportunityStageId) &&
    settings[it.opportunityStageId]?.isActive != 'N' }
    .sort { settings[it.opportunityStageId]?.sequenceNum ?: it.sequenceNum ?: 0 }
firstStageId = active ? active[0].opportunityStageId : null
firstStageProbability = active ?
    (settings[firstStageId]?.defaultProbability != null ? settings[firstStageId].defaultProbability : active[0].defaultProbability) : null

def orgContacts = ec.entity.find('zenith.erp.contacts.ContactListView')
    .condition('ownerPartyId', lead.organizationPartyId).list()
def match = orgContacts.find { row ->
    (lead.email && row.emailAddress?.equalsIgnoreCase(lead.email)) ||
    ((lead.mobile ?: lead.phone) && row.phoneNumber?.replaceAll(/\D/, '') ==
        (lead.mobile ?: lead.phone).replaceAll(/\D/, '')) }
if (reusePartyId && !orgContacts.any { it.partyId == reusePartyId })
    ec.message.addError('The selected contact is not in your organization.')
if (!reusePartyId && match)
    ec.message.addError('Matching contact ' + match.partyId + ' exists. Enter its ID to link it instead of creating a duplicate.')

def allowed = [Leads:['period','leadSourceId','firstTouchSourceId','latestTouchSourceId','campaignId','statusId','assignedToUserId'],
    Pipeline:['period','ownerId','searchText'], Activities:['period','view'],
    Reports:['period','sourceId','campaignId']]
filterName = filterName?.trim()
if (!allowed.containsKey(screenName) || !filterName || filterName.length() > 60) {
    ec.message.addError('Choose a CRM screen and a view name up to 60 characters.'); return
}
def values = allowed[screenName].findAll { context[it]?.toString()?.trim() }
    .collectEntries { key -> [(key):context[key].toString().trim().take(100)] }
filterJson = groovy.json.JsonOutput.toJson(values)

segmentUpdate = [segmentId:segmentId]
['segmentName','description','segmentTypeEnumId','isActive','isAutoEvaluate'].each { key ->
    if (context.containsKey(key)) segmentUpdate[key] = context[key]
}
if (segmentUpdate.containsKey('segmentName')) segmentUpdate.segmentName = segmentUpdate.segmentName?.trim()

import org.slf4j.LoggerFactory def logger = LoggerFactory.getLogger("GdprServices")
String scrambledHash = "ANON_" + java.util.UUID.randomUUID().toString().substring(0, 8).toUpperCase()
if (person) { person.firstName = scrambledHash person.lastName = "Redacted" person.birthDate = null person.maritalStatusEnumId = null person.employmentStatusEnumId = null person.update() logger.info("GDPR: Person Name/DOB anonymized for Party [${partyId}]") }
